insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('ff7a9f1d-9186-47bb-a244-8ebc0e5ec88d', 'KAKAUA  CACAO', generar_slug_unico('KAKAUA  CACAO', 'ff7a9f1d-9186-47bb-a244-8ebc0e5ec88d'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Rionegro', (select id from veredas where municipio = 'Rionegro' and slug = 'portachuelo'), 'FINCA ESTADO MERIDA VEREDA POTACHUELO RIONEGRO SANTANDER', 7.324333333333333, -73.16044444444445, 'Kakaua cacao nace con el proposito de fortalecer la economia campesina y urbana mediante el valor agregado en el procesamiento de subproductos y productos…', 'Kakaua cacao nace con el proposito de fortalecer la economia campesina y urbana mediante el valor agregado en el procesamiento de subproductos y productos del cacao para la diversificación e innovación de productos finales de calidad y saludables. Mediante el aprovechamiento al 100% de las potencialidades del cacao, producen chocolatina en tabletas, chocolate de mesa, truffas,nuevo producto cacao maduro , artesanias y empaques. De esta manera, promueven la generación de empleo, mejoran y fortalecen el ambiente promoviendo la producción agroforestal (BOSQUE). Kakauacacao produce, transforma y comercializa su producto final.', 'BARRAS DE CHOCOLATINA EN TABLETA', '3223167282', '573223167282', 'malibucomasjimenez@gmail.com', 'YASMIN COMAS JIMENEZ', '63462833-1', 'Natural', null, '33 MESES', 'Camara de comercio', 'XIMENA REYES', 'ACTIVO', 'Satisfactorio', null, 2022, '899 msnm', '73°9''37,6''''', '7°19''27,6''''', 'ACTUALIZO', 'Se realizo visita y se actualizo ficha de verificacion', null, 'NO', 'ACUEDUCTO VEREDAL', null, null, null, 'NO', 'NO', 'SI', null, null, null, 'SI', '2029-12-05', null, 'NO', null, null, null, null, 'NO', 'B2C', 'NO', 'NO', null, null, null, null, null, 'PARTICIPACION BIOEXPO 2023,  COP 16 Y FRNV', null, 'Aprovechamiento de agua lluvia, cultivo de cacao en asocio de frutales y nativos, abonos organicos, empaques 100% biodegradables en caña de azucar', 'Contrata personas locales, y capacita a mujeres campesinas cabeza de hogar en la realizacion de artesanias con el residuo del cacao como oportunidad de generar empleo en la zona', 'Se enfoca en desarrollo de nuevos productos con base en investigaciones que aporten a la salud del consumidor conservando las propiedades naturales del cacao,como una estrategia de diferenciacion', 'No tiene identificado sus impactos ambientales negativos dentro de la cadena productiva, y le falta detallar sus fichas tenicas de producto', 'No cuenta con SSST', 'No cuenta con un modelo de planeación y gestión que considere el triple impacto', false, false, true, false, true);
